return [
  {
    json: {
      payments: $("payments").all().map(i => i.json),
      invoice: $("Invoice Data").first(),
      pricing: $("Pricing").first().json,
      usage_logs: $("usage logs").all().map(i => i.json),
      invoice_items: $("Invoice Items").all().map(i => i.json)
    }
  }
];

const data = $('Merge Data').first()

// --- Deduplicate helper ---
const dedupeById = (arr) => {
  const seen = new Set();
  return arr.filter(item => {
    if (seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
};

// --- Clean data ---
const usageLogs = dedupeById(data.json.usage_logs);
const payments = dedupeById(data.json.payments);
const invoiceItems = dedupeById(data.json.invoice_items);

// --- Compute values ---
const totalUsage = usageLogs.reduce((sum, log) => {
  return sum + log.units_consumed;
}, 0);

const calculatedTotal = totalUsage * data.json.pricing.unit_price;

const paidAmount = payments
  .filter(p => p.status === "SUCCESS")
  .reduce((sum, p) => sum + p.amount, 0);

const pendingAmount = payments
  .filter(p => p.status === "PENDING")
  .reduce((sum, p) => sum + p.amount, 0);

const extraCharges = invoiceItems
  .filter(i => i.description !== "API Usage Charges")
  .map(i => ({
    type: i.description,
    amount: i.total
  }));

// --- Final normalized payload ---
return [
  {
    json: {
      invoice_id: data.json.invoice.json.invoice_id,
      customer_id: data.json.invoice.json.customer_id,

      invoice_total: data.json.invoice.json.total_amount,
      calculated_total: calculatedTotal,

      usage_units: totalUsage,
      unit_price: data.json.pricing.unit_price,

      extra_charges: extraCharges,

      payments: {
        paid: paidAmount,
        pending: pendingAmount
      }
    }
  }
];

let raw = $input.first().json.output[0].content[0].text;

if (typeof raw !== "string") {
  raw = JSON.stringify(raw);
}

raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  return [
    {
      json: {
        parse_error: true,
        raw_ai_output: raw,
        recommended_action: "ESCALATE",
        classification: "NEEDS_HUMAN_REVIEW",
        confidence: 0,
        internal_note: "AI output could not be parsed as JSON."
      }
    }
  ];
}

return [
  {
    json: parsed
  }
];

const data = $input.first().json;

const escalationClassifications = [
  "BILLING_ERROR",
  "DUPLICATE_CHARGE",
  "NEEDS_HUMAN_REVIEW"
];

let needsEscalation = false;
let reasons = [];

if (data.billing_valid === false) {
  needsEscalation = true;
  reasons.push("Billing validation failed");
}

if (Number(data.confidence) < 0.8) {
  needsEscalation = true;
  reasons.push("AI confidence below threshold");
}

if (escalationClassifications.includes(data.classification)) {
  needsEscalation = true;
  reasons.push(`Classification requires escalation: ${data.classification}`);
}

const ticketPriority = needsEscalation ? "Highest" : "Medium";
const ticketType = needsEscalation ? "ESCALATION" : "NORMAL_DISPUTE";

return [
  {
    json: {
      ...data,
      needs_escalation: needsEscalation,
      escalation_reasons: reasons,
      ticket_type: ticketType,
      jira_priority: ticketPriority,
      notify_team_email: needsEscalation
    }
  }
];
